import"./modulepreload-polyfill.js";const c=new Map;async function o(){const n=await chrome.tabs.query({}),t=document.getElementById("tabs");t.innerHTML="",n.filter(e=>e.id&&e.url&&!e.url.startsWith("chrome://")).forEach(e=>{const s=document.createElement("div");s.className="tab";const a=document.createElement("input");a.type="checkbox",a.dataset.tabId=e.id;const l=document.createElement("span");l.className="tab-title",l.textContent=e.title||e.url;const r=document.createElement("span");r.className="status",r.textContent=c.get(e.id)||"",s.append(a,l,r),t.appendChild(s)})}document.getElementById("recordSelected").onclick=async()=>{const n=document.querySelectorAll("input[type=checkbox]:checked");for(const t of n){const e=Number(t.dataset.tabId),s=await chrome.tabs.get(e);c.set(e,"Recording"),chrome.runtime.sendMessage({type:"START_RECORDING",tabId:e,title:s.title||`Tab ${e}`})}o()};document.getElementById("pauseAll").onclick=()=>{c.forEach((n,t)=>{c.set(t,"Paused"),chrome.runtime.sendMessage({type:"PAUSE_RECORDING",tabId:t})}),o()};document.getElementById("resumeAll").onclick=()=>{c.forEach((n,t)=>{c.set(t,"Recording"),chrome.runtime.sendMessage({type:"RESUME_RECORDING",tabId:t})}),o()};document.getElementById("stopAll").onclick=()=>{c.forEach((n,t)=>{chrome.runtime.sendMessage({type:"STOP_RECORDING",tabId:t})}),c.clear(),o()};o();
